    cellPoints[6] = 8;
    cellPoints[7] = 2;
    cells.append(cellShape(hex, cellPoints));

    cellPoints.resize(6);
    cellPoints[0] = 13;
    cellPoints[1] = 4;
    cellPoints[2] = 5;
    cellPoints[3] = 14;
    cellPoints[4] = 15;
